import pathlib,json,subprocess
p=pathlib.Path('/tmp/mangrove-page-header-source-20261006');session=(p/'session.txt').read_text().strip()
def call(*args,stdin=None):
 r=subprocess.run(['agent-browser','--session',session,*args],input=stdin,text=True,capture_output=True);(p/'logo-equivalence-driver.log').open('a').write(r.stderr);r.check_returncode();return r.stdout
inp=json.loads((p/'logo-equivalence-input.json').read_text())
js='''(async()=>{const input=INPUT; async function load(svg){const img=new Image(); img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);await img.decode();return img;}const logos={};for(const[name,l]of Object.entries(input.logos))logos[name]={...l,original:await load(l.source),images:await Promise.all(l.chunks.map(load))};const cases=[];for(const [key,c] of Object.entries(input.cases)){const name=c.image.src.split('/').pop(),l=logos[name],nw=c.image.naturalWidth,nh=c.image.naturalHeight;if(l.original.naturalWidth!==nw||l.original.naturalHeight!==nh)throw Error('Natural source size changed');const w=c.owner.width,h=c.owner.height,s=c.objectFit==='cover'?Math.max(w/nw,h/nh):Math.min(w/nw,h/nh),ow=nw*s,oh=nh*s;const pos=c.objectPosition.split(' ').map(parseFloat);if(pos.some(x=>!Number.isFinite(x)))throw Error('Source percent object position');const ox=(w-ow)*pos[0]/100,oy=(h-oh)*pos[1]/100,vw=l.viewBox[2],vh=l.viewBox[3],vs=Math.min(ow/vw,oh/vh),aw=vw*vs,ah=vh*vs,ax=ox+(ow-aw)/2,ay=oy+(oh-ah)/2;const a=document.createElement('canvas'),b=document.createElement('canvas');a.width=b.width=Math.ceil(w);a.height=b.height=Math.ceil(h);const ac=a.getContext('2d'),bc=b.getContext('2d');ac.drawImage(l.original,ox,oy,ow,oh);for(const im of l.images)bc.drawImage(im,ax,ay,aw,ah);const ap=ac.getImageData(0,0,a.width,a.height).data,bp=bc.getImageData(0,0,b.width,b.height).data;let pixels=0,max=0;for(let i=0;i<ap.length;i+=4){let different=false;for(let j=0;j<4;j++){const n=Math.abs(ap[i+j]-bp[i+j]);max=Math.max(max,n);if(n)different=true;}if(different)pixels++;}cases.push({key,sourceSVG:name,sourceOwner:c.owner,sourceNatural:{width:nw,height:nh},sourceObjectFit:c.objectFit,sourceObjectPosition:c.objectPosition,artwork:{x:ax,y:ay,width:aw,height:ah},chunks:l.chunks.length,pixelDifferences:pixels,maxChannelDifference:max,canvas:{width:a.width,height:a.height}});}return {sourceOnly:true,method:'Canvas draws exact original decoded HTTP SVG versus whole-path chunk overlay with actual IMG natural-size/object-fit/object-position allocations; source-equivalence diagnostic, not native Figma pixels.',cases};})()'''.replace('INPUT',json.dumps(inp,separators=(',',':')))
(p/'logo-equivalence.js').write_text(js)
try:
 call('open','http://localhost:6121/iframe.html?id=components-pageheader--default&viewMode=story');result=call('eval','--stdin',stdin=js);(p/'logo-equivalence.json').write_text(result)
finally:call('close')
d=json.loads(result);print('cases',len(d['cases']),'nonzero',sum(c['pixelDifferences']>0 for c in d['cases']),'maxPixels',max(c['pixelDifferences'] for c in d['cases']))
